BEGIN;
-- Canonical P1-09 analytical reconciliation. Forward-only: released 0010 remains unchanged.
UPDATE intel.semantic_registry SET classification_default=upper(classification_default) WHERE classification_default<>upper(classification_default);
ALTER TABLE intel.semantic_registry ALTER COLUMN classification_default SET DEFAULT 'INTERNAL';
UPDATE intel.projection_facts SET classification=upper(classification) WHERE classification<>upper(classification);
ALTER TABLE intel.projection_facts ALTER COLUMN classification SET DEFAULT 'INTERNAL';
UPDATE intel.metric_definitions SET classification=upper(classification) WHERE classification<>upper(classification);
ALTER TABLE intel.metric_definitions ALTER COLUMN classification SET DEFAULT 'INTERNAL';
ALTER TABLE intel.semantic_registry DROP CONSTRAINT IF EXISTS semantic_registry_classification_default_check;
ALTER TABLE intel.semantic_registry ADD CONSTRAINT semantic_registry_classification_default_check CHECK(classification_default IN ('PUBLIC_OPERATIONAL','INTERNAL','CONFIDENTIAL','PERSONAL_DATA','SENSITIVE_OPERATIONAL'));
ALTER TABLE intel.projection_facts DROP CONSTRAINT IF EXISTS projection_facts_classification_check;
ALTER TABLE intel.projection_facts ADD CONSTRAINT projection_facts_classification_check CHECK(classification IN ('PUBLIC_OPERATIONAL','INTERNAL','CONFIDENTIAL','PERSONAL_DATA','SENSITIVE_OPERATIONAL'));
ALTER TABLE intel.metric_definitions DROP CONSTRAINT IF EXISTS metric_definitions_classification_check;
ALTER TABLE intel.metric_definitions ADD CONSTRAINT metric_definitions_classification_check CHECK(classification IN ('PUBLIC_OPERATIONAL','INTERNAL','CONFIDENTIAL','PERSONAL_DATA','SENSITIVE_OPERATIONAL'));

ALTER TABLE intel.projection_facts ADD COLUMN IF NOT EXISTS value_presence text NOT NULL DEFAULT 'PRESENT';
ALTER TABLE intel.projection_facts ADD COLUMN IF NOT EXISTS team_id uuid;
ALTER TABLE intel.projection_facts ADD COLUMN IF NOT EXISTS field_officer_membership_id uuid;
ALTER TABLE intel.projection_facts ADD COLUMN IF NOT EXISTS source_completed_at timestamptz;
ALTER TABLE intel.projection_facts DROP CONSTRAINT IF EXISTS projection_facts_value_presence_check;
ALTER TABLE intel.projection_facts ADD CONSTRAINT projection_facts_value_presence_check CHECK(value_presence IN ('PRESENT','NULL'));
ALTER TABLE intel.projection_facts DROP CONSTRAINT IF EXISTS projection_facts_grain_check;
ALTER TABLE intel.projection_facts ADD CONSTRAINT projection_facts_grain_check CHECK(projection_grain IN ('SUBMISSION','FIELD_VALUE','REPEAT_ITEM','MULTI_SELECT_VALUE','EVIDENCE_FACT','ASSIGNMENT_FACT','SYNC_FACT','WORKFLOW_FACT','GEO_POINT'));
ALTER TABLE intel.projection_facts ADD CONSTRAINT projection_facts_team_fk FOREIGN KEY(organization_id,team_id) REFERENCES core.teams(organization_id,id);
ALTER TABLE intel.projection_facts ADD CONSTRAINT projection_facts_officer_fk FOREIGN KEY(organization_id,field_officer_membership_id) REFERENCES iam.memberships(organization_id,id);

CREATE TABLE intel.semantic_mappings(
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  template_version_id uuid NOT NULL,
  field_id text NOT NULL,
  semantic_key text NOT NULL REFERENCES intel.semantic_registry(semantic_key),
  value_type text NOT NULL,
  unit text,
  analytics_role text NOT NULL,
  classification text NOT NULL,
  compatibility_state text NOT NULL CHECK(compatibility_state IN ('COMPATIBLE','CONVERTIBLE','INCOMPATIBLE','UNKNOWN')),
  conversion_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(organization_id,template_version_id,field_id),
  FOREIGN KEY(organization_id,template_version_id) REFERENCES blueprint.template_versions(organization_id,id)
);
CREATE OR REPLACE FUNCTION intel.prevent_semantic_mapping_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'published semantic mapping is immutable'; END $$;
CREATE TRIGGER trg_semantic_mapping_immutable BEFORE UPDATE OR DELETE ON intel.semantic_mappings FOR EACH ROW EXECUTE FUNCTION intel.prevent_semantic_mapping_mutation();

CREATE TABLE intel.projection_freshness(
  organization_id uuid NOT NULL,
  projection_version text NOT NULL,
  lifecycle_state text NOT NULL CHECK(lifecycle_state IN ('PENDING','BUILDING','CURRENT','STALE','FAILED','REBUILDING')),
  latest_eligible_source_timestamp timestamptz,
  latest_projected_source_timestamp timestamptz,
  projected_at timestamptz,
  lag_seconds numeric NOT NULL DEFAULT 0 CHECK(lag_seconds>=0),
  failure_status text,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(organization_id,projection_version),
  FOREIGN KEY(organization_id) REFERENCES iam.organizations(id)
);

ALTER TABLE intel.semantic_mappings ENABLE ROW LEVEL SECURITY; ALTER TABLE intel.semantic_mappings FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON intel.semantic_mappings USING(organization_id=platform.current_organization_id()) WITH CHECK(organization_id=platform.current_organization_id());
ALTER TABLE intel.projection_freshness ENABLE ROW LEVEL SECURITY; ALTER TABLE intel.projection_freshness FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON intel.projection_freshness USING(organization_id=platform.current_organization_id()) WITH CHECK(organization_id=platform.current_organization_id());
GRANT SELECT ON intel.semantic_mappings,intel.projection_freshness TO app_runtime,bf_readonly;
GRANT SELECT,INSERT,UPDATE,DELETE ON intel.semantic_mappings,intel.projection_freshness TO worker_runtime;
INSERT INTO platform.rls_registry(schema_name,table_schema,table_name,policy_mode,tenant_owned,organization_column,rls_enabled,rls_forced,owning_module,runtime_roles,notes) VALUES
('intel','intel','semantic_mappings','ORGANIZATION_ID',true,'organization_id',true,true,'intel',ARRAY['app_runtime','worker_runtime'],'P1-09 immutable field-to-semantic publication mapping'),
('intel','intel','projection_freshness','ORGANIZATION_ID',true,'organization_id',true,true,'intel',ARRAY['app_runtime','worker_runtime'],'P1-09 projection freshness state')
ON CONFLICT(table_schema,table_name) DO UPDATE SET schema_name=excluded.schema_name,policy_mode=excluded.policy_mode,rls_enabled=excluded.rls_enabled,rls_forced=excluded.rls_forced,notes=excluded.notes;

