CREATE INDEX IF NOT EXISTS projection_facts_org_grain_time_idx ON intel.projection_facts(organization_id,projection_grain,source_accepted_at DESC) WHERE active;
CREATE INDEX IF NOT EXISTS projection_facts_org_project_grain_idx ON intel.projection_facts(organization_id,project_id,projection_grain) WHERE active;
CREATE INDEX IF NOT EXISTS semantic_mappings_org_semantic_idx ON intel.semantic_mappings(organization_id,semantic_key,template_version_id);
COMMIT;
